def order(a, m):
    if math.gcd(a, m) != 1:
        return None
    phi = 0
    for i in range(1, m + 1):
        if math.gcd(i, m) == 1:
            phi += 1

    d = 1
    while d * d <= phi:
        if phi % d == 0:
            if pow(a, d, m) == 1:
                return d
            if pow(a, phi // d, m) == 1:
                pass # will find the smallest one later
        d += 1

    # More robustly:
    divisors = []
    for i in range(1, int(phi**0.5) + 1):
        if phi % i == 0:
            divisors.append(i)
            divisors.append(phi // i)
    divisors = sorted(list(set(divisors)))
    for d in divisors:
        if pow(a, d, m) == 1:
            return d
    return None

import math
print(f"ord_16(3): {order(3, 16)}")
print(f"ord_625(3): {order(3, 625)}")
print(f"ord_10000(3): {order(3, 10000)}")
